void setup() {
  pinMode(LED, OUTPUT);      // 이 핀을 출력으로
}
void loop() {
  digitalWrite(LED, HIGH);   // 핀에 전압 → 켜짐
  delay(500);
  digitalWrite(LED, LOW);    // 핀 전압 0 → 꺼짐
  delay(500);
}
// 핀 설정 + 출력 + 타이밍 = 임베디드의 뼈대

pinMode(LED, OUTPUT);          // 출력: 전압을 냄
pinMode(BTN, INPUT_PULLUP);    // 입력 + 내장 풀업 (floating 방지)

void loop() {
  int v = digitalRead(BTN);    // 평소 HIGH, 누르면 LOW
  digitalWrite(LED, v == LOW ? HIGH : LOW);
}
// 출력 핀 전류는 제한(수십 mA) — 모터는 드라이버로

// 디지털
int pressed = digitalRead(BTN);      // 0 또는 1
digitalWrite(LED, HIGH);             // 켜짐/꺼짐

// 아날로그 입력(ADC): 연속 전압 → 숫자
int light = analogRead(SENSOR);      // 0~1023 (10비트)

// 아날로그 출력(PWM): 듀티로 밝기/속도
analogWrite(LED, 128);               // 0~255 = 0~100% 듀티 (약 50%)

unsigned long lastChange = 0;
int stable = HIGH, lastRead = HIGH;

void loop() {
  int r = digitalRead(BTN);
  if (r != lastRead) { lastChange = millis(); lastRead = r; }
  if (millis() - lastChange > 30) {   // 30ms 안정되면
    if (r != stable) { stable = r; if (stable == LOW) onPress(); }
  }
}

// 나쁨: delay 는 통째로 멈춤
digitalWrite(LED, HIGH); delay(500);
digitalWrite(LED, LOW); delay(500);  // 이 1초간 버튼 못 읽음

// 좋음: millis 로 「시간 됐나」 확인 (비차단)
unsigned long last = 0;
void loop() {
  if (millis() - last >= 500) { last = millis(); toggleLED(); }
  readButton();   // 멈추지 않고 매 루프 실행
}
